From 5f93be183c93e6c463d0246bf31a7c11b1ad90f1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:59:39 +0100
Subject: [PATCH] gmenu-dbusmenu-proxy: Show the icons GTK apps set on menu
 items

GTK sends item icons as a serialized GIcon, which we read as an empty
string and then replaced with our own action name icon anyway. Read the
themed icon name and only use the action name table as a fallback.

BUG: 436463
---
 gmenu-dbusmenu-proxy/window.cpp | 38 ++++++++++++++++++++++++++++++---
 1 file changed, 35 insertions(+), 3 deletions(-)

diff --git a/gmenu-dbusmenu-proxy/window.cpp b/gmenu-dbusmenu-proxy/window.cpp
index 7567a9ae6c..50f1682315 100644
--- a/gmenu-dbusmenu-proxy/window.cpp
+++ b/gmenu-dbusmenu-proxy/window.cpp
@@ -8,6 +8,7 @@

 #include "debug.h"

+#include <QDBusArgument>
 #include <QDBusConnection>
 #include <QDBusMessage>
 #include <QDBusPendingCallWatcher>
@@ -30,6 +31,35 @@ static const QString s_applicationActionsPrefix = QStringLiteral("app.");
 static const QString s_unityActionsPrefix = QStringLiteral("unity.");
 static const QString s_windowActionsPrefix = QStringLiteral("win.");

+// GTK sends a serialized GIcon, e.g. ('themed', <['document-open', 'document-open-symbolic']>)
+static QString iconName(const QVariant &icon)
+{
+    if (icon.typeId() == QMetaType::QString) {
+        return icon.toString();
+    }
+
+    if (!icon.canConvert<QDBusArgument>()) {
+        return QString();
+    }
+
+    QString type;
+    QDBusVariant value;
+    const QDBusArgument argument = icon.value<QDBusArgument>();
+    if (argument.currentSignature() != QLatin1String("(sv)")) {
+        return QString();
+    }
+    argument.beginStructure();
+    argument >> type >> value;
+    argument.endStructure();
+
+    if (type != QLatin1String("themed")) {
+        return QString();
+    }
+
+    const QStringList names = value.variant().toStringList();
+    return names.value(0);
+}
+
 Window::Window(const QString &serviceName)
     : QObject()
     , m_serviceName(serviceName)
@@ -617,12 +647,14 @@ QVariantMap Window::gMenuToDBusMenuProperties(const QVariantMap &source) const

     result.insert(QStringLiteral("visible"), visible);

-    QString icon = source.value(QStringLiteral("icon")).toString();
+    QString icon = iconName(source.value(QStringLiteral("icon")));
     if (icon.isEmpty()) {
-        icon = source.value(QStringLiteral("verb-icon")).toString();
+        icon = iconName(source.value(QStringLiteral("verb-icon")));
     }

-    icon = Icons::actionIcon(actionName);
+    if (icon.isEmpty()) {
+        icon = Icons::actionIcon(actionName);
+    }
     if (!icon.isEmpty()) {
         result.insert(QStringLiteral("icon-name"), icon);
     }
